import { Component, computed, input, model } from '@angular/core';
import { NzButtonModule, NzButtonSize } from 'ng-zorro-antd/button';
import { HrmButtonSize } from './hrm-button';

/** hrm-toggle-button — nút giữ trạng thái bật/tắt (pressed). ng-zorro không có sẵn → tự build.
 *  pressed = model hai chiều; bật = nzType primary, tắt = default. Có aria-pressed cho screen-reader.
 *  Dùng: <hrm-toggle-button [(pressed)]="bold" ariaLabel="In đậm"><tabler-icon [icon]="IconBold" /></hrm-toggle-button> */
@Component({
  selector: 'hrm-toggle-button',
  imports: [NzButtonModule],
  template: `
    <button
      nz-button
      [nzType]="pressed() ? 'primary' : 'default'"
      [nzSize]="nzSize()"
      [disabled]="disabled()"
      [class.hrm-btn-icon-only]="iconOnly()"
      [attr.aria-pressed]="pressed()"
      [attr.aria-label]="ariaLabel() || null"
      (click)="toggle()">
      <ng-content />
    </button>
  `,
  host: { class: 'hrm-toggle-button' },
})
export class HrmToggleButton {
  /** Trạng thái bật/tắt — hai chiều [(pressed)]. */
  readonly pressed = model(false);
  readonly size = input<HrmButtonSize>('md');
  readonly disabled = input(false);
  /** Nút chỉ có biểu tượng (vuông) — nhớ set ariaLabel. */
  readonly iconOnly = input(false);
  /** Nhãn cho screen-reader (bắt buộc khi iconOnly). */
  readonly ariaLabel = input('');

  protected readonly nzSize = computed<NzButtonSize>(() =>
    this.size() === 'sm' ? 'small' : this.size() === 'lg' ? 'large' : 'default');

  protected toggle(): void {
    if (!this.disabled()) this.pressed.update((v) => !v);
  }
}
